document.addEventListener('DOMContentLoaded', () => {
  // State
  let candidatesData = [];
  let currentCandidate = null;
  let selectedFile = null;

  // DOM Elements
  const tabButtons = document.querySelectorAll('.nav-item');
  const tabPanes = document.querySelectorAll('.tab-pane');
  const pageTitle = document.getElementById('pageTitle');

  // Stats
  const statTotal = document.getElementById('statTotalCandidates');
  const statShortlistRate = document.getElementById('statShortlistRate');
  const countShortlisted = document.getElementById('countShortlisted');
  const countRejected = document.getElementById('countRejected');

  // Kanban
  const cardsShortlisted = document.getElementById('cardsShortlisted');
  const cardsRejected = document.getElementById('cardsRejected');
  const filterRole = document.getElementById('filterRole');
  const searchInput = document.getElementById('searchCandidate');

  // Screener Form
  const screeningForm = document.getElementById('screeningForm');
  const fullNameInput = document.getElementById('fullName');
  const emailInput = document.getElementById('email');
  const phoneInput = document.getElementById('phoneNumber');
  const roleSelect = document.getElementById('appliedRole');
  const cvTextInput = document.getElementById('cvDirectText');
  const cvFileInput = document.getElementById('cvFile');
  const pdfDropzone = document.getElementById('pdfDropzone');
  const fileSelectedText = document.getElementById('fileSelectedText');
  const liveResultContainer = document.getElementById('liveResultContainer');
  const btnSubmitScreen = document.getElementById('btnSubmitScreen');

  // Presets
  const presetHighFrontend = document.getElementById('presetHighFrontend');
  const presetHighHR = document.getElementById('presetHighHR');
  const presetLowFrontend = document.getElementById('presetLowFrontend');

  // Simulator
  const waChatBody = document.getElementById('waChatBody');
  const tgChatBody = document.getElementById('tgChatBody');

  // Modal
  const candidateModal = document.getElementById('candidateModal');
  const btnCloseModal = document.getElementById('btnCloseModal');
  const modalCandidateName = document.getElementById('modalCandidateName');
  const modalCandidateRole = document.getElementById('modalCandidateRole');
  const modalScoreValue = document.getElementById('modalScoreValue');
  const modalDecisionText = document.getElementById('modalDecisionText');
  const modalStatusSelect = document.getElementById('modalStatusSelect');
  const barSkillFill = document.getElementById('barSkillFill');
  const barSkillVal = document.getElementById('barSkillVal');
  const barExpFill = document.getElementById('barExpFill');
  const barExpVal = document.getElementById('barExpVal');
  const barRelFill = document.getElementById('barRelFill');
  const barRelVal = document.getElementById('barRelVal');
  const modalAiSummary = document.getElementById('modalAiSummary');
  const modalMatchedSkills = document.getElementById('modalMatchedSkills');
  const modalMissingSkills = document.getElementById('modalMissingSkills');
  const modalNotifList = document.getElementById('modalNotifList');

  // Global Actions
  const btnResetDemo = document.getElementById('btnResetDemo');
  const btnQuickTest = document.getElementById('btnQuickTest');

  // Predefined Sample CV Text Payloads
  const SAMPLES = {
    highFrontend: {
      fullName: "Budi Santoso",
      email: "budi.santoso@techcorp.id",
      phone: "081234567890",
      role: "Senior Frontend Developer",
      cvText: `BUDI SANTOSO
Senior Frontend Engineer | Jakarta, Indonesia
Email: budi.santoso@techcorp.id | Phone: 081234567890 | GitHub: github.com/budisantoso

PROFESSIONAL SUMMARY
Results-driven Senior Frontend Engineer with 5+ years of extensive experience architecting high-traffic web applications using React, TypeScript, Next.js and TailwindCSS. Proven track record in optimizing Core Web Vitals, reducing bundle size by 40% and leading frontend engineering squads in fast-paced agile environments.

KEY TECHNICAL SKILLS
• Frameworks & Core: React, TypeScript, JavaScript (ES6+), Next.js, Redux Toolkit, HTML5, CSS3, TailwindCSS
• APIs & Tools: RESTful APIs, GraphQL, Git, Webpack, Vite, Docker, Jest, CI/CD pipelines
• Architecture: Micro-frontends, Server-Side Rendering (SSR), Component Design Systems

WORK EXPERIENCE
Senior Frontend Developer — PT Digital Nusantara (2021 – Present)
• Architected core customer-facing e-commerce portal using Next.js, React and TypeScript serving 1.2M monthly active users.
• Integrated REST APIs and GraphQL microservices, implementing optimistic UI updates and robust error boundaries.
• Mentored 6 junior/mid frontend engineers and maintained 90%+ Jest unit test coverage.

Frontend Engineer — FinTech Solusi Asia (2019 – 2021)
• Built interactive analytics dashboards using React, Redux and TailwindCSS.
• Integrated secure payment gateways and customer authentication flows via REST APIs.

EDUCATION
Bachelor of Science in Computer Science — Universitas Indonesia (2015 – 2019) | GPA: 3.82/4.00`
    },
    highHR: {
      fullName: "Siti Rahmawati",
      email: "siti.rahmawati@talentgroup.id",
      phone: "087788991122",
      role: "HR Recruitment Specialist",
      cvText: `SITI RAHMAWATI
Talent Acquisition Specialist | Jakarta, Indonesia
Email: siti.rahmawati@talentgroup.id | Phone: 087788991122 | LinkedIn: linkedin.com/in/sitirahmawati

EXECUTIVE PROFILE
Passionate Talent Acquisition & HR Recruitment Specialist with 4 years of end-to-end recruitment experience in the Indonesian tech and FMCG startup ecosystem. Expert in talent sourcing via LinkedIn Recruiter, competency-based interviewing, ATS management and psychological assessments. Successfully closed 140+ tech & business positions with a 92% retention rate.

CORE COMPETENCIES
• Talent Acquisition & Headhunting
• End-to-End Recruitment Lifecycle
• Competency-Based Interviewing & STAR Method
• Applicant Tracking Systems (ATS: Greenhouse, Lever, Workable)
• Indonesian Labor Law & Employment Contracts
• Employer Branding & Campus Recruitment
• Onboarding & Candidate Nurturing

PROFESSIONAL EXPERIENCE
Recruitment Specialist — PT Startup Inovasi Indonesia (2022 – Present)
• Managed full-cycle recruitment for Engineering, Product and Sales divisions.
• Sourced high-calibre candidates via LinkedIn Recruiter and tech talent communities, cutting time-to-hire by 35%.
• Administered psychological assessment batteries and organized quarterly recruitment job fairs.

Talent Acquisition Associate — People First Consulting (2020 – 2022)
• Coordinated screening calls, interview schedules and salary negotiation for 80+ candidates per quarter.
• Led employer branding campaigns that boosted qualified inbound applicants by 45%.

EDUCATION & CERTIFICATIONS
• Bachelor of Psychology — Universitas Gadjah Mada (2016 – 2020)
• Certified Human Resource Professional (CHRP) — 2021`
    },
    lowFrontend: {
      fullName: "Andi Pratama",
      email: "andi.pratama@gmail.com",
      phone: "085612344321",
      role: "Senior Frontend Developer",
      cvText: `ANDI PRATAMA
Junior Web Designer & Content Creator
Email: andi.pratama@gmail.com | Phone: 085612344321 | Bandung, Indonesia

SUMMARY
Enthusiastic junior web enthusiast with 6 months of internship experience managing WordPress websites, editing basic HTML templates and creating social media graphics with Canva. Looking for an opportunity to step into Senior Frontend Developer roles.

SKILLS
• HTML5, Basic CSS, WordPress Elementor
• Adobe Photoshop, Canva
• Microsoft Office Suite, Google Docs
• Basic JavaScript knowledge

EXPERIENCE
WordPress Web Administrator (Internship) — Media Kreatif Bandung (Jan 2024 – Jun 2024)
• Uploaded blog articles and updated banner images on client WordPress websites.
• Made minor adjustments to CSS colors and font styling.
• Created weekly social media promotional posters using Canva.

EDUCATION
High School Diploma (SMA Negeri 1 Bandung) — Graduated 2023`
    }
  };

  // Tab Navigation Handling
  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      tabButtons.forEach(b => b.classList.remove('active'));
      tabPanes.forEach(p => p.classList.remove('active'));

      btn.classList.add('active');
      const targetTab = btn.getAttribute('data-tab');
      document.getElementById(targetTab).classList.add('active');

      const titles = {
        'tab-crm': 'Talent Pipeline Dashboard',
        'tab-screener': 'AI Qualification Screener',
        'tab-simulator': 'Notification Hub & Communication Simulator',
        'tab-architecture': 'System Pipeline & Process Flow'
      };
      pageTitle.textContent = titles[targetTab] || 'Recruiter Portal';
    });
  });

  btnQuickTest.addEventListener('click', () => {
    document.querySelector('[data-tab="tab-screener"]').click();
  });

  // Load Candidates
  async function fetchCandidates() {
    try {
      const res = await fetch('/api/candidates');
      const json = await res.json();
      if (json.success) {
        candidatesData = json.data;
        renderAll();
      }
    } catch (err) {
      console.error('Failed to fetch candidates:', err);
    }
  }

  // Render Kanban & Stats & Devices
  function renderAll() {
    renderStats();
    renderKanban();
    renderDeviceSimulators();
  }

  function renderStats() {
    const total = candidatesData.length;
    const shortlisted = candidatesData.filter(c => c.match_score >= 75).length;
    const rate = total > 0 ? Math.round((shortlisted / total) * 100) : 0;

    statTotal.textContent = total;
    statShortlistRate.textContent = `${rate}%`;
    countShortlisted.textContent = shortlisted;
    countRejected.textContent = total - shortlisted;
  }

  function renderKanban() {
    const roleVal = filterRole.value;
    const searchVal = searchInput.value.toLowerCase().trim();

    let filtered = candidatesData;
    if (roleVal !== 'ALL') {
      filtered = filtered.filter(c => c.applied_role === roleVal);
    }
    if (searchVal) {
      filtered = filtered.filter(c => 
        c.full_name.toLowerCase().includes(searchVal) ||
        c.applied_role.toLowerCase().includes(searchVal) ||
        (c.key_skills && c.key_skills.some(s => s.toLowerCase().includes(searchVal)))
      );
    }

    const shortList = filtered.filter(c => c.match_score >= 75);
    const rejectList = filtered.filter(c => c.match_score < 75);

    cardsShortlisted.innerHTML = shortList.length === 0 
      ? '<div class="empty-state" style="height:120px;"><p>No shortlisted candidates found.</p></div>'
      : shortList.map(createCardHTML).join('');

    cardsRejected.innerHTML = rejectList.length === 0
      ? '<div class="empty-state" style="height:120px;"><p>No rejected candidates found.</p></div>'
      : rejectList.map(createCardHTML).join('');

    // Attach click listeners to cards
    document.querySelectorAll('.candidate-card').forEach(card => {
      card.addEventListener('click', () => {
        const id = card.getAttribute('data-id');
        openCandidateModal(id);
      });
    });
  }

  function createCardHTML(c) {
    const isHigh = c.match_score >= 75;
    const scoreClass = isHigh ? 'score-high' : 'score-low';
    const skillsHtml = (c.key_skills || []).slice(0, 4)
      .map(s => `<span class="mini-skill-tag">${escapeHtml(s)}</span>`)
      .join('');

    const formattedDate = new Date(c.applied_at).toLocaleDateString('id-ID', {
      day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit'
    });

    return `
      <div class="candidate-card" data-id="${c.id}">
        <div class="candidate-card-top">
          <div>
            <div class="cand-name">${escapeHtml(c.full_name)}</div>
            <div class="cand-role">💼 ${escapeHtml(c.applied_role)}</div>
          </div>
          <span class="score-badge ${scoreClass}">
            ${c.match_score}/100
          </span>
        </div>

        <div class="cand-skills-row">
          ${skillsHtml}
        </div>

        <div class="card-footer">
          <span>🕒 ${formattedDate}</span>
          <span class="notif-tag">
            ${isHigh ? '📱 WA Invite Sent' : '✉️ Rejection Sent'}
          </span>
        </div>
      </div>
    `;
  }

  function renderDeviceSimulators() {
    // Populate WhatsApp Chat
    const waMessages = [];
    const tgMessages = [];

    candidatesData.forEach(c => {
      (c.notifications || []).forEach(n => {
        if (n.channel === 'WhatsApp') {
          waMessages.push({ ...n, candidateName: c.full_name });
        } else if (n.channel === 'Telegram') {
          tgMessages.push({ ...n, candidateName: c.full_name });
        }
      });
    });

    // Sort newest last
    waMessages.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
    tgMessages.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

    waChatBody.innerHTML = waMessages.length === 0
      ? '<div style="color:rgba(255,255,255,0.4); text-align:center; padding:30px 0;">No WhatsApp invites dispatched yet.</div>'
      : waMessages.map(m => {
          const waUrl = m.wa_url || `https://wa.me/${m.recipient}?text=${encodeURIComponent(m.message)}`;
          return `
            <div class="chat-bubble wa-bubble">
              <p>${escapeHtml(m.message)}</p>
              <div style="margin-top: 8px;">
                <a href="${waUrl}" target="_blank" rel="noopener noreferrer" class="btn-wa-direct">
                  <span>💬</span> Open Chat (+${escapeHtml(m.recipient)})
                </a>
              </div>
              <div class="bubble-time">${new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} &bull; Delivered ✓✓</div>
            </div>
          `;
        }).join('');

    tgChatBody.innerHTML = tgMessages.length === 0
      ? '<div style="color:rgba(255,255,255,0.4); text-align:center; padding:30px 0;">No Telegram alerts yet.</div>'
      : tgMessages.map(m => `
          <div class="chat-bubble tg-bubble">
            <p style="white-space: pre-line;">${escapeHtml(m.message)}</p>
            <div class="bubble-time">${new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
          </div>
        `).join('');

    // Scroll to bottom
    waChatBody.scrollTop = waChatBody.scrollHeight;
    tgChatBody.scrollTop = tgChatBody.scrollHeight;
  }

  // Filter & Search Handlers
  filterRole.addEventListener('change', renderKanban);
  searchInput.addEventListener('input', renderKanban);

  // Preset Loaders
  presetHighFrontend.addEventListener('click', () => loadPreset(SAMPLES.highFrontend));
  presetHighHR.addEventListener('click', () => loadPreset(SAMPLES.highHR));
  presetLowFrontend.addEventListener('click', () => loadPreset(SAMPLES.lowFrontend));

  function loadPreset(preset) {
    fullNameInput.value = preset.fullName;
    emailInput.value = preset.email;
    phoneInput.value = preset.phone;
    roleSelect.value = preset.role;
    cvTextInput.value = preset.cvText;
    selectedFile = null;
    fileSelectedText.textContent = "Using preset direct CV text";
  }

  // PDF File Dropzone Handling
  cvFileInput.addEventListener('change', (e) => {
    if (e.target.files && e.target.files[0]) {
      selectedFile = e.target.files[0];
      fileSelectedText.textContent = `Selected: ${selectedFile.name} (${Math.round(selectedFile.size / 1024)} KB)`;
    }
  });

  pdfDropzone.addEventListener('dragover', (e) => {
    e.preventDefault();
    pdfDropzone.style.borderColor = 'var(--primary)';
  });

  pdfDropzone.addEventListener('dragleave', () => {
    pdfDropzone.style.borderColor = '';
  });

  pdfDropzone.addEventListener('drop', (e) => {
    e.preventDefault();
    pdfDropzone.style.borderColor = '';
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      selectedFile = e.dataTransfer.files[0];
      fileSelectedText.textContent = `Selected: ${selectedFile.name} (${Math.round(selectedFile.size / 1024)} KB)`;
    }
  });

  // Screening Form Submission
  screeningForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    const formData = new FormData();
    formData.append('full_name', fullNameInput.value.trim());
    formData.append('email', emailInput.value.trim());
    formData.append('phone_number', phoneInput.value.trim());
    formData.append('applied_role', roleSelect.value);

    if (selectedFile) {
      formData.append('cv_file', selectedFile);
    } else if (cvTextInput.value.trim()) {
      formData.append('direct_cv_text', cvTextInput.value.trim());
    } else {
      alert('Please upload a PDF CV or paste the CV text.');
      return;
    }

    btnSubmitScreen.disabled = true;
    btnSubmitScreen.innerHTML = '<span class="btn-icon">⏳</span> Analyzing CV with AI...';

    try {
      const res = await fetch('/api/apply', {
        method: 'POST',
        body: formData
      });

      const data = await res.json();
      if (data.success && data.candidate) {
        // Render Live Output Panel
        renderLiveResult(data.candidate);
        // Refresh Candidate List & Dashboard
        await fetchCandidates();
      } else {
        alert(data.error || 'Failed to evaluate CV');
      }
    } catch (err) {
      console.error('Error submitting application:', err);
      alert('Error during CV screening submission: ' + err.message);
    } finally {
      btnSubmitScreen.disabled = false;
      btnSubmitScreen.innerHTML = '<span class="btn-icon">⚡</span> Run AI Qualification Screening';
    }
  });

  function renderLiveResult(c) {
    const isHigh = c.match_score >= 75;
    const scoreColorClass = isHigh ? 'green' : 'red';

    liveResultContainer.className = 'live-result';
    liveResultContainer.innerHTML = `
      <div class="modal-score-banner" style="margin-bottom: 16px;">
        <div class="score-circle ${scoreColorClass}">${c.match_score}</div>
        <div class="score-details">
          <h3 style="color:${isHigh ? '#34D399' : '#F87171'}">${c.decision}</h3>
          <p>${c.full_name} &bull; ${c.applied_role}</p>
        </div>
      </div>

      <div class="ai-summary-box" style="margin-bottom: 16px;">
        <h4>💡 AI Evaluation Reasoning</h4>
        <p>${escapeHtml(c.ai_summary)}</p>
      </div>

      <div class="skills-grid" style="margin-bottom: 16px;">
        <div>
          <h4>Extracted Skills</h4>
          <div class="skill-tags">
            ${(c.key_skills || []).map(s => `<span class="skill-tag">${escapeHtml(s)}</span>`).join('')}
          </div>
        </div>
        <div>
          <h4>Missing Skills</h4>
          <div class="skill-tags missing">
            ${(c.missing_skills || []).length > 0
              ? c.missing_skills.map(s => `<span class="skill-tag">${escapeHtml(s)}</span>`).join('')
              : '<span style="font-size:0.8rem; color:#94A3B8;">None</span>'}
          </div>
        </div>
      </div>

      <div class="notif-history">
        <h4>⚡ Automated Action Triggered</h4>
        <div class="notif-timeline">
          ${(c.notifications || []).map(n => `
            <div class="timeline-item">
              <div class="timeline-top">
                <span class="channel-tag">${n.channel} (${n.status})</span>
                <span class="timeline-time">Just now</span>
              </div>
              <div class="timeline-msg">${escapeHtml(n.message)}</div>
            </div>
          `).join('')}
        </div>
      </div>
    `;
  }

  // Modal Detail Handling
  function openCandidateModal(id) {
    currentCandidate = candidatesData.find(c => c.id === id);
    if (!currentCandidate) return;

    const c = currentCandidate;
    const isHigh = c.match_score >= 75;

    modalCandidateName.textContent = c.full_name;
    modalCandidateRole.textContent = c.applied_role;
    modalScoreValue.textContent = c.match_score;
    modalScoreValue.className = `score-circle ${isHigh ? 'green' : 'red'}`;
    modalDecisionText.textContent = c.decision;
    modalDecisionText.style.color = isHigh ? '#34D399' : '#F87171';
    modalStatusSelect.value = c.status || (isHigh ? 'Shortlisted' : 'Rejected');

    // Progress Bars
    const bk = c.breakdown || { skills_score: c.match_score, experience_score: 75, relevance_score: 75 };
    barSkillFill.style.width = `${bk.skills_score}%`;
    barSkillVal.textContent = `${bk.skills_score}%`;

    barExpFill.style.width = `${bk.experience_score}%`;
    barExpVal.textContent = `${bk.experience_score}%`;

    barRelFill.style.width = `${bk.relevance_score}%`;
    barRelVal.textContent = `${bk.relevance_score}%`;

    modalAiSummary.textContent = c.ai_summary;

    modalMatchedSkills.innerHTML = (c.key_skills || []).length > 0
      ? c.key_skills.map(s => `<span class="skill-tag">${escapeHtml(s)}</span>`).join('')
      : '<span style="font-size:0.8rem; color:#94A3B8;">None</span>';

    modalMissingSkills.innerHTML = (c.missing_skills || []).length > 0
      ? c.missing_skills.map(s => `<span class="skill-tag">${escapeHtml(s)}</span>`).join('')
      : '<span style="font-size:0.8rem; color:#94A3B8;">None</span>';

    modalNotifList.innerHTML = (c.notifications || []).length > 0
      ? c.notifications.map(n => {
          const waButton = (n.channel === 'WhatsApp')
            ? `<div style="margin-top:6px;"><a href="${n.wa_url || `https://wa.me/${n.recipient}?text=${encodeURIComponent(n.message)}`}" target="_blank" rel="noopener noreferrer" class="btn-wa-direct"><span>💬</span> Open Chat (+${escapeHtml(n.recipient)})</a></div>`
            : '';
          return `
            <div class="timeline-item">
              <div class="timeline-top">
                <span class="channel-tag">${n.channel} &bull; ${n.status}</span>
                <span class="timeline-time">${new Date(n.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <div class="timeline-msg">${escapeHtml(n.message)}</div>
              ${waButton}
            </div>
          `;
        }).join('')
      : '<div style="color:var(--text-muted); font-size:0.8rem;">No notifications recorded.</div>';

    candidateModal.classList.add('open');
  }

  btnCloseModal.addEventListener('click', () => {
    candidateModal.classList.remove('open');
  });

  candidateModal.addEventListener('click', (e) => {
    if (e.target === candidateModal) {
      candidateModal.classList.remove('open');
    }
  });

  modalStatusSelect.addEventListener('change', async () => {
    if (!currentCandidate) return;
    try {
      await fetch(`/api/candidates/${currentCandidate.id}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: modalStatusSelect.value })
      });
      await fetchCandidates();
    } catch (err) {
      console.error('Failed to update candidate status:', err);
    }
  });

  // Reset Demo Data
  btnResetDemo.addEventListener('click', async () => {
    if (confirm('Reset candidates database to initial sample records?')) {
      try {
        const res = await fetch('/api/reset-demo', { method: 'POST' });
        const json = await res.json();
        if (json.success) {
          candidatesData = json.data;
          renderAll();
          alert('Demo data successfully restored.');
        }
      } catch (err) {
        console.error('Failed to reset demo data:', err);
      }
    }
  });

  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  // Initial Load
  fetchCandidates();
});

