  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-main);
  color: var(--text-primary);
  line-height: 1.5;
  overflow-x: hidden;
  background-image: 
    radial-gradient(circle at 10% 20%, rgba(99, 102, 241, 0.08) 0%, transparent 40%),
    radial-gradient(circle at 90% 80%, rgba(16, 185, 129, 0.05) 0%, transparent 40%);
  min-height: 100vh;
}

/* App Layout Grid */
.app-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  min-height: 100vh;
}

/* Sidebar */
.sidebar {
  background: var(--bg-sidebar);
  border-right: 1px solid var(--border-color);
  padding: 24px 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: sticky;
  top: 0;
  height: 100vh;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 8px 24px;
  border-bottom: 1px solid var(--border-color);
}

.brand-icon {
  font-size: 28px;
  background: rgba(99, 102, 241, 0.15);
  border: 1px solid var(--border-glow);
  width: 46px;
  height: 46px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
}

.brand-text h2 {
  font-size: 1.1rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 6px;
}

.badge-tag {
  font-size: 0.65rem;
  background: var(--primary-glow);
  color: #c7d2fe;
  padding: 2px 6px;
  border-radius: var(--radius-full);
  font-weight: 600;
}

.brand-text p {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.nav-menu {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 24px;
  flex-grow: 1;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: left;
}

.nav-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-primary);
}

.nav-item.active {
  background: rgba(99, 102, 241, 0.15);
  border-color: rgba(99, 102, 241, 0.3);
  color: #EEF2FF;
}

.sidebar-footer {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-top: 16px;
  border-top: 1px solid var(--border-color);
}

.engine-badge {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: rgba(16, 185, 129, 0.08);
  border: 1px solid var(--accent-green-border);
  border-radius: var(--radius-sm);
}

.status-indicator {
  width: 8px;
  height: 8px;
  background: var(--accent-green);
  border-radius: 50%;
  box-shadow: 0 0 10px var(--accent-green);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0% { transform: scale(0.95); opacity: 0.8; }
  50% { transform: scale(1.15); opacity: 1; }
  100% { transform: scale(0.95); opacity: 0.8; }
}

.engine-title {
  font-size: 0.8rem;
  font-weight: 700;
  color: #6EE7B7;
}

.engine-sub {
  font-size: 0.7rem;
  color: var(--text-muted);
}

.btn-reset {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn-reset:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
}

/* Main Content */
.main-content {
  padding: 32px;
  overflow-y: auto;
  max-width: 1400px;
}

/* Top Header */
.top-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.top-header h1 {
  font-size: 1.8rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-top: 4px;
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary), #4F46E5);
  color: #fff;
  border: none;
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 4px 14px var(--primary-glow);
  transition: all 0.2s ease;
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px var(--primary-glow);
}

/* Metrics Row */
.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 32px;
}

.metric-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  backdrop-filter: blur(12px);
  padding: 20px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  gap: 16px;
  transition: transform 0.2s ease;
}

.metric-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-glow);
}

.metric-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.metric-icon.blue { background: rgba(59, 130, 246, 0.15); border: 1px solid rgba(59, 130, 246, 0.3); }
.metric-icon.green { background: var(--accent-green-bg); border: 1px solid var(--accent-green-border); }
.metric-icon.purple { background: rgba(139, 92, 246, 0.15); border: 1px solid rgba(139, 92, 246, 0.3); }
.metric-icon.amber { background: rgba(245, 158, 11, 0.15); border: 1px solid rgba(245, 158, 11, 0.3); }

.metric-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  font-weight: 700;
}

.metric-info h3 {
  font-size: 1.6rem;
  font-weight: 800;
  line-height: 1.2;
  margin: 2px 0;
}

.metric-sub {
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.text-success {
  color: #34D399;
}

/* Tabs */
.tab-pane {
  display: none;
}

.tab-pane.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Kanban Board */
.kanban-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  gap: 16px;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.filter-group label {
  font-size: 0.85rem;
  color: var(--text-secondary);
  font-weight: 600;
}

.form-select, .form-input, .form-textarea {
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 0.9rem;
  outline: none;
  transition: border-color 0.2s ease;
}

.form-select:focus, .form-input:focus, .form-textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary-glow);
}

.search-box input {
  width: 280px;
}

.kanban-board {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.kanban-column {
  background: rgba(15, 23, 42, 0.4);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 16px;
  display: flex;
  flex-direction: column;
  min-height: 500px;
}

.column-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 14px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border-color);
}

.col-title {
  display: flex;
  align-items: center;
  gap: 8px;
}

.col-title h3 {
  font-size: 1rem;
  font-weight: 700;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.green-dot { background: var(--accent-green); box-shadow: 0 0 8px var(--accent-green); }
.red-dot { background: var(--accent-red); box-shadow: 0 0 8px var(--accent-red); }

.counter-badge {
  background: rgba(255, 255, 255, 0.08);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-secondary);
}

.column-cards {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex-grow: 1;
}

/* Candidate Card */
.candidate-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px;
  cursor: pointer;
  transition: all 0.2s ease;
  backdrop-filter: blur(10px);
}

.candidate-card:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-glow);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.candidate-card-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 8px;
}

.cand-name {
  font-size: 1.05rem;
  font-weight: 700;
  color: #fff;
}

.cand-role {
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-top: 2px;
}

.score-badge {
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 800;
  font-family: var(--font-mono);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.score-high {
  background: var(--accent-green-bg);
  border: 1px solid var(--accent-green-border);
  color: #34D399;
}

.score-low {
  background: var(--accent-red-bg);
  border: 1px solid var(--accent-red-border);
  color: #F87171;
}

.cand-skills-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 10px 0;
}

.mini-skill-tag {
  font-size: 0.7rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  color: #CBD5E1;
}

.card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 10px;
  margin-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  font-size: 0.75rem;
  color: var(--text-muted);
}

.notif-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #38BDF8;
}

/* Screener Layout */
.screener-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  backdrop-filter: blur(16px);
}

.card-header {
  margin-bottom: 20px;
}

.card-header h2 {
  font-size: 1.25rem;
  font-weight: 700;
}

.card-header p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

.sample-presets {
  background: rgba(99, 102, 241, 0.08);
  border: 1px solid var(--border-glow);
  padding: 14px;
  border-radius: var(--radius-md);
  margin-bottom: 20px;
}

.preset-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #A5B4FC;
  display: block;
  margin-bottom: 8px;
}

.preset-buttons {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.btn-preset {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
  transition: all 0.2s ease;
}

.btn-preset:hover {
  background: rgba(99, 102, 241, 0.2);
  border-color: var(--primary);
}

.screening-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-group label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
}

/* Dropzone */
.dropzone {
  border: 2px dashed rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  position: relative;
  cursor: pointer;
  background: rgba(15, 23, 42, 0.4);
  transition: all 0.2s ease;
}

.dropzone:hover {
  border-color: var(--primary);
  background: rgba(99, 102, 241, 0.05);
}

.file-input {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}

.upload-icon {
  font-size: 32px;
  display: block;
  margin-bottom: 6px;
}

.dropzone-text {
  font-size: 0.85rem;
  color: var(--text-primary);
  font-weight: 600;
}

.browse-link {
  color: var(--primary);
  text-decoration: underline;
}

.dropzone-sub {
  font-size: 0.75rem;
  color: var(--text-muted);
  display: block;
  margin-top: 4px;
}

.btn-submit {
  width: 100%;
  padding: 14px;
  justify-content: center;
  font-size: 1rem;
  margin-top: 8px;
}

/* Right Panel Live Result */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 380px;
  text-align: center;
  color: var(--text-muted);
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  padding: 24px;
}

.empty-icon {
  font-size: 48px;
  margin-bottom: 12px;
  opacity: 0.6;
}

.empty-state h3 {
  color: var(--text-secondary);
  font-size: 1.1rem;
  margin-bottom: 6px;
}

.empty-state p {
  font-size: 0.85rem;
  max-width: 320px;
}

/* Device Simulator */
.hub-header {
  margin-bottom: 24px;
}

.hub-header h2 {
  font-size: 1.4rem;
  font-weight: 800;
}

.hub-header p {
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.simulator-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.device-card {
  background: #020617;
  border: 1px solid var(--border-color);
  border-radius: 28px;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  height: 540px;
}

.device-top {
  padding: 10px 0;
  display: flex;
  justify-content: center;
  background: #020617;
}

.device-speaker {
  width: 50px;
  height: 5px;
  background: #1E293B;
  border-radius: var(--radius-full);
}

.app-bar {
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.wa-header {
  background: #075E54;
  color: #fff;
}

.tg-header {
  background: #2481CC;
  color: #fff;
}

.wa-avatar, .tg-avatar {
  font-size: 22px;
  width: 38px;
  height: 38px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.wa-info h4, .tg-info h4 {
  font-size: 0.9rem;
  font-weight: 700;
}

.wa-info p, .tg-info p {
  font-size: 0.7rem;
  opacity: 0.8;
}

.wa-chat-body, .tg-chat-body {
  flex-grow: 1;
  padding: 16px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.wa-chat-body {
  background-color: #0b141a;
  background-image: radial-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 16px 16px;
}

.tg-chat-body {
  background: #0e1621;
}

.chat-bubble {
  max-width: 85%;
  padding: 10px 14px;
  border-radius: 12px;
  font-size: 0.85rem;
  line-height: 1.4;
  position: relative;
  animation: fadeIn 0.3s ease;
}

.wa-bubble {
  background: #005c4b;
  color: #e9edef;
  align-self: flex-start;
  border-bottom-left-radius: 2px;
}

.tg-bubble {
  background: #182533;
  color: #f5f5f5;
  align-self: flex-start;
  border-bottom-left-radius: 2px;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.bubble-time {
  font-size: 0.65rem;
  color: rgba(255, 255, 255, 0.5);
  text-align: right;
  margin-top: 4px;
}

.wa-footer, .tg-footer {
  padding: 12px 16px;
  background: #111b21;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  text-align: center;
}

.wa-input-mock, .tg-input-mock {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Architecture Tab */
.arch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
}

.arch-card h2 {
  font-size: 1.4rem;
  font-weight: 800;
}

.arch-sub {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin: 6px 0 28px;
}

.flow-steps-grid {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 32px;
}

.flow-step-box {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px 16px;
  flex: 1;
  text-align: center;
}

.step-num {
  font-size: 0.75rem;
  font-family: var(--font-mono);
  color: var(--primary);
  font-weight: 800;
  margin-bottom: 6px;
}

.step-icon {
  font-size: 28px;
  margin-bottom: 8px;
}

.flow-step-box h4 {
  font-size: 0.9rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.flow-step-box p {
  font-size: 0.75rem;
  color: var(--text-secondary);
  line-height: 1.3;
}

.flow-step-arrow {
  color: var(--primary);
  font-size: 20px;
  opacity: 0.6;
}

.routing-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.split-card {
  padding: 20px;
  border-radius: var(--radius-md);
}

.green-card {
  background: var(--accent-green-bg);
  border: 1px solid var(--accent-green-border);
}

.red-card {
  background: var(--accent-red-bg);
  border: 1px solid var(--accent-red-border);
}

.split-badge {
  font-size: 0.8rem;
  font-weight: 800;
  margin-bottom: 12px;
  letter-spacing: 0.05em;
}

.green-card .split-badge { color: #34D399; }
.red-card .split-badge { color: #F87171; }

.split-card ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 0.85rem;
  color: #E2E8F0;
}

/* Modal */
.modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background: rgba(3, 7, 18, 0.8);
  backdrop-filter: blur(8px);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal-backdrop.open {
  display: flex;
  animation: fadeIn 0.2s ease;
}

.modal-card {
  background: #0F172A;
  border: 1px solid var(--border-glow);
  width: 90%;
  max-width: 680px;
  max-height: 90vh;
  border-radius: var(--radius-lg);
  overflow-y: auto;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.7);
}

.modal-header {
  padding: 20px 24px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modal-header-info h2 {
  font-size: 1.3rem;
  font-weight: 800;
}

.modal-role-badge {
  font-size: 0.8rem;
  color: #A5B4FC;
  background: rgba(99, 102, 241, 0.15);
  padding: 2px 8px;
  border-radius: var(--radius-full);
  margin-top: 4px;
  display: inline-block;
}

.btn-close {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 24px;
  cursor: pointer;
}

.btn-close:hover {
  color: #fff;
}

.modal-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.modal-score-banner {
