const fs = require('fs');
const path = require('path');
const { PDFDocument, rgb, StandardFonts } = require('pdf-lib');

const sampleDir = path.join(__dirname, '..', 'sample_cvs');
if (!fs.existsSync(sampleDir)) {
  fs.mkdirSync(sampleDir, { recursive: true });
}

async function createProfessionalPdf(filename, data) {
  const pdfDoc = await PDFDocument.create();
  const page = pdfDoc.addPage([595.28, 841.89]); // A4
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  const { width, height } = page.getSize();
  let y = height - 50;

  // Header Title
  page.drawText(data.name, { x: 50, y, size: 18, font: fontBold, color: rgb(0.1, 0.15, 0.3) });
  y -= 22;
  page.drawText(data.title, { x: 50, y, size: 12, font: fontBold, color: rgb(0.3, 0.35, 0.5) });
  y -= 18;
  page.drawText(`Email: ${data.email}  |  Phone: ${data.phone}  |  Location: ${data.location}`, {
    x: 50, y, size: 9, font: fontRegular, color: rgb(0.4, 0.4, 0.4)
  });
  y -= 20;

  // Divider Line
  page.drawLine({
    start: { x: 50, y },
    end: { x: width - 50, y },
    thickness: 1,
    color: rgb(0.8, 0.8, 0.8)
  });
  y -= 20;

  // Sections
  for (const section of data.sections) {
    if (y < 80) break;
    page.drawText(section.heading, { x: 50, y, size: 11, font: fontBold, color: rgb(0.15, 0.2, 0.4) });
    y -= 14;

    for (const item of section.items) {
      if (y < 60) break;
      page.drawText(item, { x: 55, y, size: 9.5, font: fontRegular, color: rgb(0.2, 0.2, 0.2) });
      y -= 14;
    }
    y -= 10;
  }

  const pdfBytes = await pdfDoc.save();
  fs.writeFileSync(path.join(sampleDir, filename), pdfBytes);
  console.log(`Successfully generated PDF: ${filename}`);
}

