const fs = require('fs');
const path = require('path');

const targetFiles = [
  'README.md',
  'SETUP_AND_CONFIGURATION_GUIDE.md',
  'n8n_AI_HR_Screening_Documentation.md',
  'server.js',
  'public/index.html',
  'public/app.js',
  'public/styles.css',
  'scripts/generate_sample_pdfs.js',
  'data/candidates.json'
];

targetFiles.forEach(relPath => {
  const fullPath = path.join(__dirname, '..', relPath);
  if (fs.existsSync(fullPath)) {
    let content = fs.readFileSync(fullPath, 'utf8');
    const before = content;
    content = content.replace(/,\s+and\b/g, ' and');
    content = content.replace(/,\s+And\b/g, ' And');
    if (content !== before) {
      fs.writeFileSync(fullPath, content, 'utf8');
      console.log(`Replaced in: ${relPath}`);
    } else {
      console.log(`No changes needed in: ${relPath}`);
    }
  }
});

files.scripts/stress_test.js:
const fs = require('fs');
const path = require('path');
const { extractText } = require('unpdf');

// Sample candidate pool for synthetic batch generation
const SAMPLE_CANDIDATES = [
  {
    name: "Budi Santoso",
    role: "Senior Frontend Developer",
    email: "budi.santoso@techcorp.id",
    phone: "081234567890",
    pdfFile: "CV_Budi_Santoso_Frontend_Lead.pdf"
  },
  {
    name: "Siti Rahmawati",
    role: "HR Recruitment Specialist",
    email: "siti.rahmawati@talentgroup.id",
    phone: "087788991122",
    pdfFile: "CV_Siti_Rahmawati_HR_Specialist.pdf"
  },
  {
    name: "Andi Pratama",
    role: "Senior Frontend Developer",
    email: "andi.pratama@gmail.com",
    phone: "085612344321",
    pdfFile: "CV_Andi_Pratama_Junior_Applicant.pdf"
  }
];

const JOB_ROLES = {
  "Senior Frontend Developer": {
    title: "Senior Frontend Developer",
    required_skills: ["React", "JavaScript", "TypeScript", "HTML5", "CSS3", "TailwindCSS", "Next.js", "Redux", "REST API", "Git"],
    preferred_skills: ["GraphQL", "CI/CD", "Jest", "UI/UX Design", "Performance Optimization"]
  },
  "HR Recruitment Specialist": {
    title: "HR Recruitment Specialist",
    required_skills: ["Talent Acquisition", "End-to-End Recruitment", "Interviewing", "Sourcing", "Applicant Tracking System", "ATS", "Psychological Assessment", "Job Fair"],
    preferred_skills: ["Employer Branding", "Indonesian Labor Law", "LinkedIn Recruiter", "HR Automation", "Onboarding"]
  },
  "Data Analyst": {
    title: "Data Analyst",
    required_skills: ["SQL", "Python", "Tableau", "Power BI", "Excel", "Data Visualization", "Statistical Analysis", "Data Cleaning"],
    preferred_skills: ["Pandas", "R", "BigQuery", "Machine Learning", "A/B Testing"]
  }
};

function normalizePhone(phone) {
  let cleaned = String(phone).replace(/\D/g, '');
  if (cleaned.startsWith('0')) cleaned = '62' + cleaned.slice(1);
  else if (cleaned.startsWith('8')) cleaned = '62' + cleaned;
  return cleaned;
}

function runLocalAIScreening(cvText, appliedRole, candidateName) {
  const roleConfig = JOB_ROLES[appliedRole] || {
    required_skills: ["Communication", "Problem Solving", "Teamwork"],
    preferred_skills: ["Leadership"]
  };

  const textLower = cvText.toLowerCase();

  const matchedRequired = roleConfig.required_skills.filter(skill => {
    const regex = new RegExp(`\\b${skill.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
    return regex.test(textLower);
  });

  const matchedPreferred = (roleConfig.preferred_skills || []).filter(skill => {
    const regex = new RegExp(`\\b${skill.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
    return regex.test(textLower);
  });

  const missingSkills = roleConfig.required_skills.filter(s => !matchedRequired.includes(s));

  const reqWeight = roleConfig.required_skills.length > 0 ? (matchedRequired.length / roleConfig.required_skills.length) : 0.7;
  const prefBonus = (roleConfig.preferred_skills && roleConfig.preferred_skills.length > 0)
    ? (matchedPreferred.length / roleConfig.preferred_skills.length) * 0.15
    : 0.05;
  const skillsScore = Math.min(100, Math.round((reqWeight * 85 + prefBonus * 100)));

  let expYears = 2;
  const expMatches = textLower.match(/(\d+)\s*(?:\+|\-)?\s*(?:years?|thn|tahun)\s*(?:of\s*)?(?:exp|experience|pengalaman)/gi);
  if (expMatches) {
    const numbers = expMatches.map(m => parseInt(m.match(/\d+/)[0], 10));
    expYears = Math.max(...numbers, 0);
  } else if (textLower.includes('senior') || textLower.includes('lead')) {
    expYears = 4;
  }

  let experienceScore = expYears >= 4 ? 95 : expYears >= 2 ? 85 : 65;

  let relevanceScore = 75;
  if (textLower.includes('experience') || textLower.includes('pengalaman kerja')) relevanceScore += 8;
  if (textLower.includes('education') || textLower.includes('pendidikan')) relevanceScore += 7;
  if (textLower.includes('project') || textLower.includes('portfolio')) relevanceScore += 10;
  relevanceScore = Math.min(100, relevanceScore);

  const totalScore = Math.round((skillsScore * 0.50) + (experienceScore * 0.30) + (relevanceScore * 0.20));
  const finalScore = Math.max(25, Math.min(98, totalScore));
  const decision = finalScore >= 75 ? "SHORTLIST" : "REJECT";

  return {
    match_score: finalScore,
    decision,
    matchedRequired,
    matchedPreferred,
    missingSkills
  };
}

async function processSingleCV(candidateData, pdfBuffer) {
  const start = performance.now();

  // 1. PDF Text Extraction
  let extractedText = '';
  if (pdfBuffer) {
    const { text } = await extractText(new Uint8Array(pdfBuffer));
    extractedText = Array.isArray(text) ? text.join('\n') : text;
  } else {
    extractedText = `Candidate: ${candidateData.name}, Role: ${candidateData.role}`;
  }

  // 2. Phone Normalization
  const phone = normalizePhone(candidateData.phone);

  // 3. AI Scoring Engine
  const evaluation = runLocalAIScreening(extractedText, candidateData.role, candidateData.name);

  // 4. Notification Dispatch Preparation
  const notifications = [];
  if (evaluation.decision === 'SHORTLIST') {
    notifications.push({
      channel: 'WhatsApp',
      to: phone,
      msgLength: 240
    });
    notifications.push({
      channel: 'Telegram',
      to: 'HR Internal Group',
      msgLength: 180
    });
  } else {
    notifications.push({
      channel: 'Email',
      to: candidateData.email,
      msgLength: 190
    });
  }

  const durationMs = performance.now() - start;
  return {
    durationMs,
    score: evaluation.match_score,
    decision: evaluation.decision,
    extractedChars: extractedText.length
  };
}

// Calculate Percentiles (P50, P90, P95, P99)
function calculatePercentiles(latencies) {
  latencies.sort((a, b) => a - b);
  const p = (pct) => {
    const idx = Math.ceil((pct / 100) * latencies.length) - 1;
    return latencies[Math.max(0, idx)].toFixed(2);
  };
  const sum = latencies.reduce((a, b) => a + b, 0);
  const avg = (sum / latencies.length).toFixed(2);
  const min = latencies[0].toFixed(2);
  const max = latencies[latencies.length - 1].toFixed(2);

  return {
    min,
    max,
    avg,
    p50: p(50),
    p90: p(90),
    p95: p(95),
    p99: p(99)
  };
}

async function runBatchBenchmark(batchSize, concurrency = 10) {
  const sampleDir = path.join(__dirname, '..', 'sample_cvs');
  const pdfBuffers = [];

  for (const c of SAMPLE_CANDIDATES) {
    const filePath = path.join(sampleDir, c.pdfFile);
    if (fs.existsSync(filePath)) {
      pdfBuffers.push({
        candidate: c,
        buffer: fs.readFileSync(filePath)
      });
    }
  }

  if (pdfBuffers.length === 0) {
    console.error("No sample PDFs found. Please generate sample PDFs first.");
    return;
  }

  console.log(`\n================================================================`);
  console.log(`🧪 RUNNING STRESS TEST BATCH: ${batchSize} RESUMES (Concurrency: ${concurrency})`);
  console.log(`================================================================`);

  const initialMem = process.memoryUsage().heapUsed / 1024 / 1024;
  const overallStart = performance.now();
  const latencies = [];
  let shortlistedCount = 0;
  let rejectedCount = 0;

  // Run in chunks matching concurrency
  const tasks = [];
  for (let i = 0; i < batchSize; i++) {
    const sample = pdfBuffers[i % pdfBuffers.length];
    tasks.push({
      candidate: {
        ...sample.candidate,
        name: `${sample.candidate.name} #${i + 1}`
      },
      buffer: sample.buffer
    });
  }

  for (let i = 0; i < tasks.length; i += concurrency) {
    const chunk = tasks.slice(i, i + concurrency);
    const chunkResults = await Promise.all(
      chunk.map(t => processSingleCV(t.candidate, t.buffer))
    );
    for (const res of chunkResults) {
      latencies.push(res.durationMs);
      if (res.decision === 'SHORTLIST') shortlistedCount++;
      else rejectedCount++;
    }
  }

  const overallDurationSec = (performance.now() - overallStart) / 1000;
  const finalMem = process.memoryUsage().heapUsed / 1024 / 1024;
  const rps = (batchSize / overallDurationSec).toFixed(2);
  const stats = calculatePercentiles(latencies);

  console.log(`📊 BENCHMARK RESULTS (Batch Size: ${batchSize}):`);
  console.log(`  • Total Pipeline Execution Time : ${overallDurationSec.toFixed(2)} seconds`);
  console.log(`  • System Throughput             : ${rps} resumes/sec (~${(rps * 60).toFixed(0)} resumes/min)`);
  console.log(`  • Shortlist Rate                : ${((shortlistedCount / batchSize) * 100).toFixed(1)}% (${shortlistedCount} shortlisted, ${rejectedCount} rejected)`);
  console.log(`  • Memory Footprint Delta        : ${(finalMem - initialMem).toFixed(2)} MB`);
  console.log(`\n⏱️ LATENCY BREAKDOWN PER RESUME:`);
  console.log(`  • Min Latency  : ${stats.min} ms`);
  console.log(`  • Avg Latency  : ${stats.avg} ms`);
  console.log(`  • P50 (Median) : ${stats.p50} ms`);
  console.log(`  • P90          : ${stats.p90} ms`);
  console.log(`  • P95          : ${stats.p95} ms`);
  console.log(`  • P99          : ${stats.p99} ms`);
  console.log(`  • Max Latency  : ${stats.max} ms`);

  return {
    batchSize,
    overallDurationSec,
    rps,
    stats,
    shortlistedCount,
    rejectedCount
  };
}

function printTimeSavingsModel(weeklyApplicants = 250, manualMinPerResume = 4) {
  const manualTotalMinutes = weeklyApplicants * manualMinPerResume;
  const manualTotalHours = (manualTotalMinutes / 60).toFixed(1);

  // Automated System calculation:
  // 1. Machine processing time: ~30-60 seconds for whole batch
  // 2. Recruiter human review time: Recruiter reviews only shortlisted candidates (top ~20%) at 1.0 min/resume
  const shortlistedRatio = 0.20; // 20% shortlisted
  const shortlistedCount = Math.round(weeklyApplicants * shortlistedRatio);
  const humanReviewMinPerShortlist = 1.0;
  const recruiterHumanMinutes = (shortlistedCount * humanReviewMinPerShortlist) + 5; // +5 mins weekly spot check
  const recruiterHumanHours = (recruiterHumanMinutes / 60).toFixed(2);
  const savingsPercent = (((manualTotalMinutes - recruiterHumanMinutes) / manualTotalMinutes) * 100).toFixed(1);

  console.log(`\n================================================================`);
  console.log(`📐 MATHEMATICAL PROJECTION MODEL & PROOF FOR RECRUITING WORKLOAD`);
  console.log(`================================================================`);
  console.log(`Assumption Parameters:`);
  console.log(`  • Weekly Applicant Inflow (Req Volume) : ${weeklyApplicants} resumes / week`);
  console.log(`  • Manual Screening Time per CV        : ${manualMinPerResume} mins / resume (Industry avg: 3–5 min)`);
  console.log(`  • System Shortlist Rate Filter         : ${(shortlistedRatio * 100)}% pass rate (${shortlistedCount} qualified candidates)`);
  console.log(`  • Recruiter Verification on Shortlist : ${humanReviewMinPerShortlist} min / shortlisted candidate`);
  console.log(`\nTime Comparison:`);
  console.log(`  ❌ Manual Screening Baseline : ${weeklyApplicants} CVs × ${manualMinPerResume} mins = ${manualTotalMinutes} mins (${manualTotalHours} hours/week)`);
  console.log(`  🤖 Machine AI Batch Screening: ${weeklyApplicants} CVs processed in ~0.5–2.0 seconds`);
  console.log(`  ✅ Recruiter Human Effort   : (${shortlistedCount} Shortlisted × 1 min) + 5m spot-check = ${recruiterHumanMinutes} mins (${recruiterHumanHours} hours/week)`);
  console.log(`  🎉 Net Human Time Reduction : ${(manualTotalHours - recruiterHumanHours).toFixed(1)} hours/week saved (${savingsPercent}% reduction)`);
  console.log(`================================================================\n`);
}

async function main() {
  const args = process.argv.slice(2);
  const customBatch = args[0] ? parseInt(args[0], 10) : 250;

  console.log(`Starting AI Screening System Stress Test & Benchmark Suite...`);

  // Run standard batch benchmark
  await runBatchBenchmark(customBatch, 10);

  // Print mathematical projection
  printTimeSavingsModel(customBatch, 4);
}

main().catch(err => console.error(err));

