function loadCandidates() {
  try {
    if (fs.existsSync(DB_FILE)) {
      const data = fs.readFileSync(DB_FILE, 'utf8');
      return JSON.parse(data);
    }
  } catch (err) {
    console.error('Error reading candidates DB:', err);
  }
  const initial = getInitialCandidates();
  saveCandidates(initial);
  return initial;
}

function saveCandidates(candidates) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(candidates, null, 2), 'utf8');
  } catch (err) {
    console.error('Error saving candidates DB:', err);
  }
}

// Phone Number Normalizer (Indonesian Format 08xxx -> 628xxx)
function normalizeIndonesianPhone(phone) {
  if (!phone) return '';
  let cleaned = String(phone).replace(/\D/g, '');
  if (cleaned.startsWith('0')) {
    cleaned = '62' + cleaned.slice(1);
  } else if (cleaned.startsWith('8')) {
    cleaned = '62' + cleaned;
  }
  return cleaned;
}

// Built-in Local Semantic & Heuristic Screening Engine (100% Free, Zero API Key Required)
function runLocalAIScreening(cvText, appliedRole, candidateName) {
  const roleConfig = JOB_ROLES[appliedRole] || {
    title: appliedRole,
    required_skills: ["Communication", "Problem Solving", "Teamwork", "Project Management"],
    preferred_skills: ["Leadership", "Analytical Thinking"]
  };

  const textLower = cvText.toLowerCase();

  // Extract Matched Skills
  const matchedRequired = roleConfig.required_skills.filter(skill => {
    const regex = new RegExp(`\\b${skill.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
    return regex.test(textLower);
  });

  const matchedPreferred = (roleConfig.preferred_skills || []).filter(skill => {
    const regex = new RegExp(`\\b${skill.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
    return regex.test(textLower);
  });

  const missingSkills = roleConfig.required_skills.filter(s => !matchedRequired.includes(s));

  // Compute Skill Match Ratio (50% weight)
  const reqWeight = roleConfig.required_skills.length > 0 ? (matchedRequired.length / roleConfig.required_skills.length) : 0.7;
  const prefBonus = (roleConfig.preferred_skills && roleConfig.preferred_skills.length > 0)
    ? (matchedPreferred.length / roleConfig.preferred_skills.length) * 0.15
    : 0.05;
  const skillsScore = Math.min(100, Math.round((reqWeight * 85 + prefBonus * 100)));

  // Experience & Depth Detection (30% weight)
  let expYears = 0;
  const expMatches = textLower.match(/(\d+)\s*(?:\+|\-)?\s*(?:years?|thn|tahun)\s*(?:of\s*)?(?:exp|experience|pengalaman)/gi);
  if (expMatches) {
    const numbers = expMatches.map(m => parseInt(m.match(/\d+/)[0], 10));
    expYears = Math.max(...numbers, 0);
  } else if (textLower.includes('senior') || textLower.includes('lead') || textLower.includes('manager')) {
    expYears = 4;
  } else if (textLower.includes('junior') || textLower.includes('intern') || textLower.includes('fresh graduate')) {
    expYears = 1;
  } else {
    expYears = 2;
  }

  let experienceScore = 70;
  if (expYears >= 4) experienceScore = 95;
  else if (expYears >= 2) experienceScore = 85;
  else if (expYears >= 1) experienceScore = 75;
  else experienceScore = 60;

  // Formatting, Projects & Structure Relevance (20% weight)
  let relevanceScore = 75;
  if (textLower.includes('experience') || textLower.includes('pengalaman kerja')) relevanceScore += 8;
  if (textLower.includes('education') || textLower.includes('pendidikan')) relevanceScore += 7;
  if (textLower.includes('project') || textLower.includes('portfolio') || textLower.includes('portofolio')) relevanceScore += 10;
  relevanceScore = Math.min(100, relevanceScore);

  // Overall Match Score
  const totalScore = Math.round((skillsScore * 0.50) + (experienceScore * 0.30) + (relevanceScore * 0.20));
  const finalScore = Math.max(25, Math.min(98, totalScore));

  const decision = finalScore >= 75 ? "SHORTLIST" : "REJECT";

  let aiSummary = "";
  const allExtractedSkills = [...matchedRequired, ...matchedPreferred];

  if (decision === "SHORTLIST") {
    aiSummary = `Kandidat ${candidateName} memiliki kecocokan tinggi (${finalScore}/100) untuk posisi ${appliedRole}. Menunjukkan penguasaan skill utama: ${matchedRequired.slice(0, 4).join(', ') || 'kompetensi inti'}, serta profil pengalaman kerja yang relevan dengan standar role.`;
  } else {
    aiSummary = `Kandidat ${candidateName} memperoleh skor ${finalScore}/100 untuk posisi ${appliedRole}. Ditemukan beberapa kesenjangan pada kualifikasi utama (${missingSkills.slice(0, 3).join(', ') || 'persyaratan teknis'}), sehingga belum mencapai ambang batas screening (>= 75).`;
  }

  return {
    match_score: finalScore,
    decision: decision,
    ai_summary: aiSummary,
    key_skills: allExtractedSkills.length > 0 ? allExtractedSkills : ["General Skills", "Communication"],
    missing_skills: missingSkills,
    breakdown: {
      skills_score: skillsScore,
      experience_score: experienceScore,
      relevance_score: relevanceScore
    }
  };
}

