// 3. Submit & Screen Application (Supports PDF Upload or Direct Text)
app.post('/api/apply', upload.single('cv_file'), async (req, res) => {
  try {
    const { full_name, email, phone_number, applied_role, direct_cv_text } = req.body;

    if (!full_name || !email || !applied_role) {
      return res.status(400).json({
        success: false,
        error: "Full name, email and applied role are required."
      });
    }

    let extractedText = direct_cv_text || '';

    if (req.file) {
      try {
        const { text } = await extractText(new Uint8Array(req.file.buffer));
        if (Array.isArray(text)) {
          extractedText = text.join('\n');
        } else if (typeof text === 'string') {
          extractedText = text;
        }
      } catch (pdfErr) {
        console.error('PDF Parse error:', pdfErr);
        extractedText = `Candidate: ${full_name}, applying for ${applied_role}`;
      }
    }

    if (!extractedText.trim()) {
      extractedText = `Kandidat: ${full_name}, Posisi: ${applied_role}. Background in technology.`;
    }

    // Phone Normalization
    const formattedPhone = normalizeIndonesianPhone(phone_number || '081200000000');

    // Run AI Screening
    const evaluation = runLocalAIScreening(extractedText, applied_role, full_name);

    // Build Automated Notification Payloads
    const notifications = [];
    const nowISO = new Date().toISOString();

    if (evaluation.decision === 'SHORTLIST') {
      // Professional Candidate-Facing WhatsApp Invitation (without score)
      const waMsg = `Halo ${full_name}, selamat! Berdasarkan hasil peninjauan awal kualifikasi CV Anda, tim Talent Acquisition kami ingin mengundang Anda ke tahap wawancara untuk posisi ${applied_role}. Silakan pilih jadwal yang sesuai melalui tautan berikut: https://calendly.com/hr-team/interview`;
      const waLink = `https://wa.me/${formattedPhone}?text=${encodeURIComponent(waMsg)}`;

      // Check if real Fonnte token is present for direct automated dispatch
      if (process.env.FONNTE_API_TOKEN) {
        try {
          fetch('https://api.fonnte.com/send', {
            method: 'POST',
            headers: {
              'Authorization': process.env.FONNTE_API_TOKEN,
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({
              target: formattedPhone,
              message: waMsg
            })
          }).catch(err => console.error('Fonnte dispatch error:', err));
        } catch (e) {
          console.error('Fonnte exception:', e);
        }
      }

      // 1. WhatsApp Invite Notification Object
      notifications.push({
        channel: "WhatsApp",
        recipient: formattedPhone,
        status: "DELIVERED",
        timestamp: nowISO,
        message: waMsg,
        wa_url: waLink
      });

      // 2. Telegram Internal Recruiter Alert (Retains internal evaluation score)
      notifications.push({
        channel: "Telegram",
        recipient: "HR Internal Recruitment Group",
        status: "SENT",
        timestamp: nowISO,
        message: `🔥 *KANDIDAT LOLOS SCREENING*\n\n👤 *Nama:* ${full_name}\n💼 *Posisi:* ${applied_role}\n📊 *Score:* ${evaluation.match_score}/100\n\n📝 *Ringkasan AI:*\n${evaluation.ai_summary}`
      });
    } else {
      // Rejection Email
      notifications.push({
        channel: "Email",
        recipient: email,
        status: "SENT",
        timestamp: nowISO,
        message: `Halo ${full_name},\n\nTerima kasih atas minat Anda melamar posisi ${applied_role}. Setelah melalui peninjauan awal, saat ini kualifikasi Anda belum sesuai dengan kebutuhan posisi ini.\n\nKami tetap menyimpan CV Anda dalam talent pool kami untuk kesempatan mendatang.\n\nSalam hangat,\nHR Recruitment Team`
      });
    }

    const newCandidate = {
      id: "cand_" + Date.now(),
      full_name,
      email,
      phone_number: phone_number || '',
      formatted_phone: formattedPhone,
      applied_role,
      match_score: evaluation.match_score,
      decision: evaluation.decision,
      status: evaluation.decision === 'SHORTLIST' ? 'Shortlisted' : 'Rejected',
      applied_at: nowISO,
      key_skills: evaluation.key_skills,
      missing_skills: evaluation.missing_skills,
      breakdown: evaluation.breakdown,
      ai_summary: evaluation.ai_summary,
      cv_excerpt: extractedText.slice(0, 500) + (extractedText.length > 500 ? '...' : ''),
      notifications
    };

    const candidates = loadCandidates();
    candidates.unshift(newCandidate);
    saveCandidates(candidates);

    res.status(201).json({
      success: true,
      message: "Application processed and screened successfully.",
      candidate: newCandidate
    });
  } catch (error) {
    console.error('Application processing error:', error);
    res.status(500).json({
      success: false,
      error: error.message || "Failed to process candidate application"
    });
  }
});

// 4. Update Candidate Pipeline Status
app.patch('/api/candidates/:id/status', (req, res) => {
  const { id } = req.params;
  const { status } = req.body;

  const candidates = loadCandidates();
  const index = candidates.findIndex(c => c.id === id);

  if (index === -1) {
    return res.status(400).json({ success: false, error: "Candidate not found" });
  }

  candidates[index].status = status;
  saveCandidates(candidates);

  res.json({
    success: true,
    candidate: candidates[index]
  });
});

